package live.linghe.privateinput;

import android.util.AtomicFile;
import java.io.*;
import java.math.BigInteger;
import java.util.*;
import org.json.*;

/** Isolated v2 files. Only authenticated protocol code may establish a policy/clock. */
final class RecentLearningStore {
 static final int MAX_BYTES=2*1024*1024;
 private final File directory;private final AtomicFile file,policyFile,receiptFile;private final String privacyEpoch;
 RecentLearningStore(File directory){this.directory=directory;file=new AtomicFile(new File(directory,"recent-learning-v2.json"));policyFile=new AtomicFile(new File(directory,"recent-learning-policy-v2.json"));receiptFile=new AtomicFile(new File(directory,"recent-learning-receipts-v1.json"));privacyEpoch=PersonalReset.fileGeneration(directory);}
 private <T>T locked(AppFiles.Work<T> work)throws Exception{synchronized(RecentLearningStore.class){if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("Recent directory unavailable");File lock=new File(directory,"recent-learning.lock");if(java.nio.file.Files.isSymbolicLink(lock.toPath()))throw new IOException("Invalid recent lock");try(RandomAccessFile holder=new RandomAccessFile(lock,"rw");java.nio.channels.FileLock held=holder.getChannel().lock()){return work.run();}}}
 private void write(AtomicFile target,String value,int limit)throws Exception{epoch();AppFiles.write(target,value,limit);}
 static void clearForDeparture(File directory)throws Exception{RecentLearningStore store=new RecentLearningStore(directory);store.locked(()->{for(String name:RecentLearningScope.PERSONAL_FILES)for(String suffix:new String[]{"",".bak",".new"})java.nio.file.Files.deleteIfExists(new File(directory,name+suffix).toPath());return null;});}
 static final class Snapshot {
  final RecentLearning model;final PersonalLexicon.Snapshot personal;
  Snapshot(RecentLearning model,PersonalLexicon.Snapshot personal){this.model=model;this.personal=personal;}
 }
 static final class PolicyState {
  final RecentLearningScope scope;final String binding;final RecentLearning.Policy policy;final RecentLearning.Clock clock;final boolean publishEnabled;
  PolicyState(String binding,RecentLearning.Policy policy,RecentLearning.Clock clock,boolean publishEnabled)throws Exception{RecentLearning.name(binding);scope=new RecentLearningScope(binding);this.binding=scope.binding;this.policy=policy;this.clock=clock;this.publishEnabled=publishEnabled;}
  String encode()throws Exception{return LosslessJson.canonical(new JSONObject().put("version",1).put("binding",binding).put("referenceDay",policy.referenceDay).put("windowDays",policy.windowDays).put("publishEnabled",publishEnabled).put("clock",new JSONObject().put("anchorUnixSeconds",clock.anchorUnixSeconds).put("anchorUptime",clock.anchorUptime).put("lastUptime",clock.lastUptime).put("bootSession",clock.bootSession).put("trusted",clock.trusted)));}
  static PolicyState decode(String text)throws Exception{JSONObject p=LosslessJson.object(text,4096),c=p.getJSONObject("clock");RecentLearning.require(LosslessJson.unsigned(p.get("version")).intValueExact()==1&&c.get("trusted") instanceof Boolean&&p.get("publishEnabled") instanceof Boolean,"Invalid recent policy");RecentLearning.Clock clock=new RecentLearning.Clock(c.getDouble("anchorUnixSeconds"),c.getDouble("anchorUptime"),PersonalLexicon.string(c,"bootSession"));clock.lastUptime=c.getDouble("lastUptime");clock.trusted=c.getBoolean("trusted");RecentLearning.require(Double.isFinite(clock.lastUptime)&&clock.lastUptime>=clock.anchorUptime,"Invalid persisted clock");return new PolicyState(PersonalLexicon.string(p,"binding"),new RecentLearning.Policy(LosslessJson.unsigned(p.get("referenceDay")).intValueExact(),LosslessJson.unsigned(p.get("windowDays")).intValueExact()),clock,p.getBoolean("publishEnabled"));}
 }
 static final class Usage {
  final double wallSeconds,uptime;final String bootSession;
  Usage(double wallSeconds,double uptime,String bootSession){this.wallSeconds=wallSeconds;this.uptime=uptime;this.bootSession=bootSession;}
 }
 private void epoch()throws Exception{if(!privacyEpoch.equals(PersonalReset.fileGeneration(directory)))throw new IOException("个人资料已重置");}
 private PolicyState readPolicy()throws Exception{String text=AppFiles.readOptional(policyFile,4096);return text==null?null:PolicyState.decode(text);}
 /** Calling this is an assertion that transport signature, group binding and writer capabilities were checked. */
 void acceptAuthenticatedPolicy(PolicyState value)throws Exception{locked(()->{epoch();PolicyState previous=readPolicy();if(previous!=null)previous.scope.validateReplacement(value.scope,previous.policy.referenceDay,value.policy.referenceDay);write(policyFile,value.encode(),4096);return null;});}
 void suspendPolicy()throws Exception{locked(()->{epoch();PolicyState p=readPolicy();if(p!=null){p.clock.trusted=false;write(policyFile,new PolicyState(p.binding,p.policy,p.clock,false).encode(),4096);}return null;});}
 static Usage usage(android.content.Context context){String boot=CACHED_BOOT;if(boot==null)synchronized(RecentLearningStore.class){boot=CACHED_BOOT;if(boot==null){try{boot=android.provider.Settings.Global.getString(context.getContentResolver(),android.provider.Settings.Global.BOOT_COUNT);}catch(Exception unavailable){boot=null;}CACHED_BOOT=boot=boot==null?"unavailable-"+PROCESS_BOOT:boot;}}return new Usage(System.currentTimeMillis()/1000.0,android.os.SystemClock.elapsedRealtime()/1000.0,boot);}
 private static volatile String CACHED_BOOT;
 private static final String PROCESS_BOOT=UUID.randomUUID().toString();
 static String legacyProjection(Snapshot snapshot)throws Exception{JSONArray entries=new JSONArray();for(RecentLearning.Entry e:snapshot.model.entries())entries.put(new LearningModel.Entry(e.reading,e.text,e.generation,e.deleted,e.counts,e.pinned,new LearningModel.Version(e.pinVersion.sequence,e.pinVersion.replica)).json());JSONObject archive=new JSONObject().put("version",1).put("schemaID","private_pinyin").put("entries",entries);if(snapshot.personal!=null)archive.put("personalLexicon",snapshot.personal.synchronizationObject());String text=LosslessJson.canonical(archive);LearningModel check=new LearningModel();check.merge(text);return text;}
 private static RecentLearning.Entry fromWord(LearningModel.Entry w,Map<Integer,Map<String,Long>> buckets)throws Exception{return new RecentLearning.Entry(w.reading,w.text,w.generation,w.deleted,w.counts,w.pinned,new RecentLearning.Version(w.pinVersion.sequence,w.pinVersion.device),buckets);}
 static Snapshot decode(String text,RecentLearning.Policy policy)throws Exception{
  JSONObject root=LosslessJson.object(text,MAX_BYTES);RecentLearning.require(LosslessJson.unsigned(root.get("version")).intValueExact()==2&&PersonalLexicon.string(root,"schemaID").equals("private_pinyin_recency")&&LosslessJson.unsigned(root.get("algorithmVersion")).intValueExact()==1,"Incompatible recent schema");JSONArray entries=root.getJSONArray("entries");RecentLearning.require(entries.length()<=5000,"Recent capacity exceeded");List<RecentLearning.Entry> values=new ArrayList<>();
  for(int i=0;i<entries.length();i++){JSONObject entry=entries.getJSONObject(i);LearningModel.Entry word=LearningModel.Entry.decode(entry.getJSONObject("word"));JSONArray source=entry.getJSONArray("buckets");RecentLearning.require(source.length()<=90,"Recent bucket capacity exceeded");Map<Integer,Map<String,Long>> buckets=new TreeMap<>();for(int j=0;j<source.length();j++){JSONObject bucket=source.getJSONObject(j);int day=LosslessJson.unsigned(bucket.get("day")).intValueExact();RecentLearning.require(!buckets.containsKey(day),"Duplicate recent day");JSONObject counts=bucket.getJSONObject("counts");Map<String,Long> map=new LinkedHashMap<>();Iterator<String> keys=counts.keys();while(keys.hasNext()){String raw=keys.next(),key=LearningModel.canonical(raw);RecentLearning.require(!map.containsKey(key),"Duplicate recent replica");map.put(key,LosslessJson.unsigned(counts.get(raw)).longValueExact());}buckets.put(day,map);}values.add(fromWord(word,buckets));}
  RecentLearning model=new RecentLearning();model.merge(values,policy);PersonalLexicon.Snapshot personal=root.has("personalLexicon")&&!root.isNull("personalLexicon")?PersonalLexicon.decodeSynchronized(root.getJSONObject("personalLexicon")):null;return new Snapshot(model,personal);
 }
 static String encode(Snapshot snapshot,RecentLearning.Policy policy)throws Exception{
  JSONArray entries=new JSONArray();List<RecentLearning.Entry> values=new ArrayList<>(snapshot.model.entries());values.sort(Comparator.comparing(RecentLearning.Entry::id));for(RecentLearning.Entry raw:values){RecentLearning.Entry e=raw.normalized(policy);LearningModel.Entry word=new LearningModel.Entry(e.reading,e.text,e.generation,e.deleted,e.counts,e.pinned,new LearningModel.Version(e.pinVersion.sequence,e.pinVersion.replica));JSONArray buckets=new JSONArray();for(Map.Entry<Integer,Map<String,Long>> b:e.buckets.entrySet()){JSONObject counts=new JSONObject();for(Map.Entry<String,Long> c:b.getValue().entrySet())counts.put(c.getKey(),c.getValue());buckets.put(new JSONObject().put("day",b.getKey()).put("counts",counts));}entries.put(new JSONObject().put("word",word.json()).put("buckets",buckets));}
  JSONObject root=new JSONObject().put("version",2).put("schemaID","private_pinyin_recency").put("algorithmVersion",1).put("entries",entries);if(snapshot.personal!=null)root.put("personalLexicon",snapshot.personal.synchronizationObject());String text=LosslessJson.canonical(root);RecentLearning.require(PersonalLexicon.bytes(text)<=MAX_BYTES,"Recent archive oversized");return text;
 }
 private Snapshot read(RecentLearning.Policy policy)throws Exception{String text=AppFiles.readOptional(file,MAX_BYTES);return text==null?new Snapshot(new RecentLearning(),null):decode(text,policy);}
 Snapshot snapshot()throws Exception{return locked(()->{epoch();PolicyState policy=readPolicy();return read(policy==null?new RecentLearning.Policy(90):policy.policy);});}
 void acceptReceipt(String binding,String event,String hash,long expires,long now)throws Exception{locked(()->{epoch();PolicyState policy=readPolicy();RecentLearning.require(policy!=null&&policy.publishEnabled&&policy.binding.equals(binding),"Recent receipt binding unavailable");RecentLearningWire.uuid(event);RecentLearning.require(java.util.Base64.getDecoder().decode(hash).length==32&&expires>now&&expires-now<=7*86400,"Invalid recent receipt");String encoded=AppFiles.readOptional(receiptFile,512*1024);JSONObject ledger=encoded==null?new JSONObject():LosslessJson.object(encoded,512*1024);if(encoded!=null)RecentLearning.require(LosslessJson.unsigned(ledger.get("version")).intValueExact()==1,"Invalid recent receipts");JSONObject events=encoded!=null&&binding.equals(ledger.getString("binding"))?ledger.getJSONObject("events"):new JSONObject();RecentLearning.require(events.length()<=4096,"Recent receipt capacity exceeded");List<String> expired=new ArrayList<>();Iterator<String> names=events.keys();while(names.hasNext()){String id=names.next();RecentLearningWire.uuid(id);JSONObject item=events.getJSONObject(id);RecentLearning.require(java.util.Base64.getDecoder().decode(item.getString("hash")).length==32,"Invalid receipt digest");if(LosslessJson.unsigned(item.get("expiresAt")).compareTo(BigInteger.valueOf(now))<=0)expired.add(id);}for(String id:expired)events.remove(id);if(events.has(event)){RecentLearning.require(events.getJSONObject(event).getString("hash").equals(hash),"Recent event fork");return null;}RecentLearning.require(events.length()<4096,"Recent receipt capacity exceeded");events.put(event,new JSONObject().put("hash",hash).put("expiresAt",expires));String next=LosslessJson.canonical(new JSONObject().put("version",1).put("binding",binding).put("events",events));write(receiptFile,next,512*1024);return null;});}
 static final class Selection {
  final String reading,text,replica,binding;final Integer day;final BigInteger generation;
  Selection(String reading,String text,String replica,BigInteger generation,PolicyState authenticated,Usage event)throws Exception{
   RecentLearning.Entry.fresh(reading,text);RecentLearning.name(replica);this.reading=reading;this.text=text;this.replica=replica;this.generation=generation;binding=authenticated==null?"":authenticated.binding;Integer dated=null;
   if(authenticated!=null&&authenticated.publishEnabled&&authenticated.clock.trusted&&event.uptime>=authenticated.clock.anchorUptime){RecentLearning.Clock evidence=new RecentLearning.Clock(authenticated.clock.anchorUnixSeconds,authenticated.clock.anchorUptime,authenticated.clock.bootSession);dated=evidence.day(event.wallSeconds,event.uptime,event.bootSession);}
   day=authenticated!=null&&dated!=null&&authenticated.policy.accepts(dated)?dated:null;
  }
 }
 /** One idle checkpoint batch, one file read/write. Never called for each key/selection. */
 Snapshot recordChoices(List<Selection> selections)throws Exception{return locked(()->{epoch();RecentLearning.require(selections.size()<=5000,"Recent batch oversized");if(new LearningCoordinator(directory,new File(directory,"Shared")).requiresPrivateRecovery())throw new IOException("输入记忆正在恢复");PolicyState p=readPolicy();RecentLearning.Policy policy=p==null?new RecentLearning.Policy(90):p.policy;Snapshot old=read(policy);RecentLearning model=old.model.copy();List<RecentLearning.SelectionDelta> deltas=new ArrayList<>();for(Selection event:selections){Integer day=p!=null&&p.publishEnabled&&p.binding.equals(event.binding)?event.day:null;deltas.add(new RecentLearning.SelectionDelta(event.reading,event.text,event.replica,day,event.generation));}model.recordConfirmedSelections(deltas,policy);Snapshot next=new Snapshot(model,old.personal);write(file,encode(next,policy),MAX_BYTES);return next;});}
 /** Explicit legacy MAX projection adds no date buckets and never rewrites v1. */
 Snapshot mergeLegacy(String text)throws Exception{return locked(()->{epoch();PolicyState p=readPolicy();RecentLearning.Policy policy=p==null?new RecentLearning.Policy(90):p.policy;LearningModel legacy=new LearningModel();legacy.merge(text);Snapshot old=read(policy);RecentLearning next=old.model.copy();List<RecentLearning.Entry> values=new ArrayList<>();for(LearningModel.Entry e:legacy.entries())values.add(fromWord(e,Collections.emptyMap()));next.merge(values,policy);PersonalLexicon.Snapshot incoming=LosslessJson.object(text,LearningModel.MAX_BYTES).has("personalLexicon")&&!LosslessJson.object(text,LearningModel.MAX_BYTES).isNull("personalLexicon")?PersonalLexicon.decodeSynchronized(LosslessJson.object(text,LearningModel.MAX_BYTES).getJSONObject("personalLexicon")):null;PersonalLexicon.Snapshot personal=old.personal;if(incoming!=null)personal=PersonalLexicon.combine(personal==null?PersonalLexicon.empty():personal,incoming);Snapshot result=new Snapshot(next,personal);write(file,encode(result,policy),MAX_BYTES);return result;});}
 Snapshot mergeAuthenticatedArchive(String text,String binding)throws Exception{return locked(()->{epoch();PolicyState p=readPolicy();RecentLearning.require(p!=null&&p.publishEnabled&&p.binding.equals(binding),"Recent policy unavailable");Snapshot old=read(p.policy),incoming=decode(text,p.policy);RecentLearning next=old.model.copy();next.merge(incoming.model.entries(),p.policy);PersonalLexicon.Snapshot personal=old.personal;if(incoming.personal!=null)personal=PersonalLexicon.combine(personal==null?PersonalLexicon.empty():personal,incoming.personal);Snapshot result=new Snapshot(next,personal);write(file,encode(result,p.policy),MAX_BYTES);return result;});}
 String outbound(String binding)throws Exception{return locked(()->{epoch();RecentLearning.require(!new LearningCoordinator(directory,new File(directory,"Shared")).requiresPrivateRecovery(),"Import pending");PolicyState p=readPolicy();RecentLearning.require(p!=null&&p.publishEnabled&&p.binding.equals(binding),"Recent policy unavailable");return encode(read(p.policy),p.policy);});}
 PolicyState policySnapshot()throws Exception{return locked(()->{epoch();return readPolicy();});}
 RecentLearning.Policy rankingPolicy(Usage now)throws Exception{return locked(()->{epoch();PolicyState p=readPolicy();if(p==null||!p.publishEnabled)return null;Integer day=p.clock.day(now.wallSeconds,now.uptime,now.bootSession);write(policyFile,p.encode(),4096);return day!=null&&p.policy.accepts(day)?p.policy:null;});}
}
